55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
75	
76	const groupByType = (items: Item[]): Item[][] => {
77	  const groups = new Map<string, Item[]>();
78	  for (const item of items) {
79	    const group = groups.get(item.type) ?? [];
80	    group.push(item);
81	    groups.set(item.type, group);
82	  }
83	  return [...groups.values()];
84	};
85	
86	const groupBasePremium = (group: Item[]): number =>
87	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(group);
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
91	
92	const withFirstInsuranceSurcharge = (policyBase: number): number =>
93	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
94	
95	const roundInMHPCOsFavor = Math.ceil;
96	
97	const quotePremium = (items: Item[]): number =>
98	  roundInMHPCOsFavor(withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE);
99	
100	const runStep = (step: Step): StepResult => {
101	  if (step.op === "quote") {
102	    return { premium: quotePremium(step.items) };
103	  }
104	  throw new Error(`Unsupported step: ${step.op}`);
105	};
106	
107	export const runScenario = (scenario: Scenario): ScenarioResult => ({
108	  results: scenario.steps.map(runStep),
109	});
